#!/usr/bin/env node
/**
 * instalar-orion.mjs — instalador autocontenido del runtime ORION.
 *
 * Escribe las 5 skills y los 7 agentes de fase donde Claude realmente los
 * carga, y opcionalmente refresca los espejos del repo en runtime/.
 * Cero dependencias. Idempotente. No borra nada: si algo cambia, guarda .bak.
 *
 *   node instalar-orion.mjs                     instala en ~/.claude
 *   node instalar-orion.mjs --check             muestra qué haría, sin escribir
 *   node instalar-orion.mjs --sync-repo <ruta>  refresca <ruta>/runtime/ también
 *   node instalar-orion.mjs --repo-only <ruta>  SOLO refresca <ruta>/runtime/
 *   node instalar-orion.mjs --home <ruta>       usa otra carpeta en vez de ~/.claude
 *
 * Después de instalar hay que REINICIAR Claude Code: skills y agentes se
 * cargan al arrancar la sesión.
 */
import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs"
import { join, dirname, resolve } from "node:path"
import { homedir } from "node:os"

const ARGV = process.argv.slice(2)
const flag = (n) => ARGV.includes(n)
const val = (n) => { const i = ARGV.indexOf(n); return i >= 0 ? ARGV[i + 1] : undefined }

const CHECK = flag("--check") || flag("--dry-run")
const CLAUDE_HOME = resolve(val("--home") ?? join(homedir(), ".claude"))
const REPO_ONLY = flag("--repo-only")
const SYNC_REPO = (flag("--sync-repo") || REPO_ONLY)
  ? resolve(val("--sync-repo") ?? val("--repo-only") ?? process.cwd())
  : null
if (REPO_ONLY && !SYNC_REPO) { console.error("--repo-only necesita la ruta del repo"); process.exit(1) }

const PAYLOAD = [
{"kind":"skill","name":"estudio-diseno","claudePath":"skills/estudio-diseno/SKILL.md","repoPath":"runtime/skills/estudio-diseno.SKILL.md","b64":""},
{"kind":"skill","name":"orion-cerebro","claudePath":"skills/orion-cerebro/SKILL.md","repoPath":"runtime/skills/orion-cerebro.SKILL.md","b64":""},
{"kind":"skill","name":"orion-close","claudePath":"skills/orion-close/SKILL.md","repoPath":"runtime/skills/orion-close.SKILL.md","b64":""},
{"kind":"skill","name":"orion-status","claudePath":"skills/orion-status/SKILL.md","repoPath":"runtime/skills/orion-status.SKILL.md","b64":""},
{"kind":"skill","name":"orion-validate","claudePath":"skills/orion-validate/SKILL.md","repoPath":"runtime/skills/orion-validate.SKILL.md","b64":""},
{"kind":"skill","name":"orion","claudePath":"skills/orion/SKILL.md","repoPath":"runtime/skills/orion.SKILL.md","b64":""},
{"kind":"agent","name":"landing-prompter","claudePath":"agents/landing-prompter.md","repoPath":"runtime/agents/landing-prompter.md","b64":""},
{"kind":"agent","name":"orion-analyst","claudePath":"agents/orion-analyst.md","repoPath":"runtime/agents/orion-analyst.md","b64":""},
{"kind":"agent","name":"orion-builder","claudePath":"agents/orion-builder.md","repoPath":"runtime/agents/orion-builder.md","b64":""},
{"kind":"agent","name":"orion-curator","claudePath":"agents/orion-curator.md","repoPath":"runtime/agents/orion-curator.md","b64":""},
{"kind":"agent","name":"orion-fixer","claudePath":"agents/orion-fixer.md","repoPath":"runtime/agents/orion-fixer.md","b64":""},
{"kind":"agent","name":"orion-harvester","claudePath":"agents/orion-harvester.md","repoPath":"runtime/agents/orion-harvester.md","b64":""},
{"kind":"agent","name":"orion-planner","claudePath":"agents/orion-planner.md","repoPath":"runtime/agents/orion-planner.md","b64":""},
{"kind":"agent","name":"orion-reflector","claudePath":"agents/orion-reflector.md","repoPath":"runtime/agents/orion-reflector.md","b64":""},
{"kind":"agent","name":"orion-verifier","claudePath":"agents/orion-verifier.md","repoPath":"runtime/agents/orion-verifier.md","b64":""}
]

const stamp = new Date().toISOString().replace(/[:.]/g, "-")
let written = 0, unchanged = 0, backed = 0
const rows = []

function put(absPath, content, label) {
  const exists = existsSync(absPath)
  const same = exists && readFileSync(absPath, "utf8") === content
  if (same) { unchanged++; rows.push(["=", label, "sin cambios"]); return }
  if (CHECK) { rows.push([exists ? "~" : "+", label, exists ? "se actualizaría" : "se crearía"]); return }
  mkdirSync(dirname(absPath), { recursive: true })
  if (exists) { writeFileSync(`${absPath}.${stamp}.bak`, readFileSync(absPath)); backed++ }
  writeFileSync(absPath, content, "utf8")
  written++
  rows.push([exists ? "~" : "+", label, exists ? "actualizado (.bak guardado)" : "creado"])
}

console.log(`\nORION — instalador del runtime${CHECK ? "  [SOLO REVISIÓN]" : ""}`)
if (!REPO_ONLY) console.log(`  destino Claude : ${CLAUDE_HOME}`)
if (SYNC_REPO) console.log(`  espejo repo    : ${join(SYNC_REPO, "runtime")}`)
console.log()

for (const it of PAYLOAD) {
  const content = Buffer.from(it.b64, "base64").toString("utf8")
  if (!REPO_ONLY) put(join(CLAUDE_HOME, ...it.claudePath.split("/")), content, `${it.kind === "skill" ? "skill " : "agente"} ${it.name}`)
  if (SYNC_REPO) put(join(SYNC_REPO, ...it.repoPath.split("/")), content, `repo   ${it.repoPath}`)
}

const w = Math.max(...rows.map((r) => r[1].length))
for (const [sig, label, note] of rows) console.log(`  ${sig} ${label.padEnd(w)}  ${note}`)

console.log(`\n  ${PAYLOAD.filter((p) => p.kind === "skill").length} skills · ${PAYLOAD.filter((p) => p.kind === "agent").length} agentes`)
console.log(`  escritos: ${written} · sin cambios: ${unchanged} · respaldos: ${backed}`)

// ── verificación: releer del disco y confirmar que cada archivo quedó bien ──
if (!CHECK) {
  const bad = []
  const targets = REPO_ONLY
    ? PAYLOAD.map((it) => [it, join(SYNC_REPO, ...it.repoPath.split("/"))])
    : PAYLOAD.map((it) => [it, join(CLAUDE_HOME, ...it.claudePath.split("/"))])
  for (const [it, p] of targets) {
    if (!existsSync(p)) { bad.push(`${it.name}: no existe`); continue }
    const t = readFileSync(p, "utf8")
    const m = /^---\n([\s\S]*?)\n---\n/.exec(t)
    if (!m) { bad.push(`${it.name}: frontmatter ilegible`); continue }
    const nm = /^name:\s*"?([^"\n]+)"?/m.exec(m[1])
    if (!nm || nm[1].trim() !== it.name) bad.push(`${it.name}: 'name' del frontmatter no coincide`)
    if (!/^description:/m.test(m[1])) bad.push(`${it.name}: sin description`)
  }
  if (bad.length) { console.log(`\n  VERIFICACIÓN: FALLÓ\n${bad.map((b) => `    - ${b}`).join("\n")}`); process.exitCode = 1 }
  else console.log(`\n  VERIFICACIÓN: los ${PAYLOAD.length} archivos quedaron en disco y parsean.`)
}

if (!CHECK && !REPO_ONLY) {
  console.log(`
  SIGUIENTE PASO: reinicia Claude Code (las skills y los agentes se cargan al
  arrancar la sesión). Luego prueba:  /orion-status

  Comandos que quedan disponibles:
    /orion <tarea>    ciclo completo con subagentes y memoria
    /orion-status     briefing barato de inicio de sesión
    /orion-close      cierre de sesión + curación de memoria
    /orion-validate   valida la memoria contra el esquema AMM
    /estudio-diseno   sistema de diseño del usuario
`)
}
